import { useDispatch, useSelector } from "react-redux";
import { useNavigate, useParams } from "react-router-dom";
import { productSelector } from "../../store/selectors/productSelectors";
import { useEffect, useState } from "react";
import {
  delProductMiddleWare,
  getProductsMiddleWare,
} from "../../store/reducers/productReducer";
import { deleteProduct } from "../../store/actions/productActions";
import ROUTES from "../../Routes";

import style from "./EachProduct.module.css";
import axios from "axios";

const EachProduct = () => {
  const { id } = useParams();
  const dispatch = useDispatch();
  const data = useSelector(productSelector);
  useEffect(() => {
    dispatch(getProductsMiddleWare());
  }, []);

console.log(data[0]);
  const filteredData = data[0]?.filter((elm) =>  elm.id == id);  
  const navigate = useNavigate();
const [input, setInput] = useState(false)

const newPrice =(e) => {
  console.log(e.target.value);

}

  return (
    <div className={style.main}>
      <div className={style.product}>
        <button className={style.edit} onClick={()=>{setInput(!input)}}>
          <img
            src="https://static-00.iconduck.com/assets.00/edit-icon-1024x1024-u3a8q4uh.png"
            alt="edit"
            className={style.editImg}
          />
        </button>
        <button
          className={style.del}
          onClick={() => {
            navigate(ROUTES.PRODUCTS,{ reset: true });
            dispatch(delProductMiddleWare(id));
          }}
        >
          X
        </button>
        <div className={style.imgDiv}>
          <img
            src={filteredData[0]?.images[0]}
            alt="photoOfProducts"
            className={style.img}
          />
          <img
            src={filteredData[0]?.images[1]}
            alt="photoOfProducts"
            className={style.img}
          />
          <img
            src={filteredData[0]?.images[2]}
            alt="photoOfProducts"
            className={style.img}
          />
        </div>
        <div className={style.details}>
          <h2>{filteredData[0]?.title}</h2>
          <p>{filteredData[0]?.description}</p>
          <h4>$ {filteredData[0]?.price}</h4>
          {/* <input type="text" placeholder="new price"/> */}
          {input ? 
          <form className="">
            <input type="text" placeholder="new price" onSubmit={(e)=>newPrice(e)}/>
<input type="submit" value='Change'/>

          </form>
          : null}
        </div>
      </div>
    </div>
  );
};

export default EachProduct;
